  `course_name` varchar(255) DEFAULT NULL,
  `catalogname` varchar(255) NOT NULL,
  `category` varchar(255) DEFAULT NULL,
  `course_num` int DEFAULT NULL,
  `course_desc` text,
  `course_credits` int DEFAULT NULL,
  `prerequisite_stmt` text,
  PRIMARY KEY (`course_id`),
  UNIQUE KEY `category` (`category`,`course_num`,`course_name`)
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `courses`
--

LOCK TABLES `courses` WRITE;
/*!40000 ALTER TABLE `courses` DISABLE KEYS */;
INSERT INTO `courses` VALUES (1,'Computer Science I','CMSC 201','CMSC',201,'An introduction to computer science through problem solving and computer programming. Programming techniques covered by this course include modularity, abstraction, top-down design, specifications documentation, debugging and testing. The core material for this course includes control structures, functions, lists, strings, abstract data types, file I/O, and recursion.',4,'Prerequisite: MATH 150, MATH 151, MATH 152, or MATH 155 with a grade of \'C\' or better or score of 5 on the Math Placement Test.'),(2,'Computer Science II','CMSC 202','CMSC',202,'This course continues the student\'s development of programming and problem-solving skills by providing an introduction to object-oriented design and programming (OOP). The primary focus is on OOP principles and techniques, including encapsulation, composition, inheritance, and polymorphism. Other OOP topics such as exception handling, containers, and generic programming are also covered. This is the second course for students interested in pursuing further study in computer science.',4,'Prerequisite: CMSC 201 or CMSC 201H with a grade of \'C\' or better. MATH 150, MATH 151, or MATH 152 with a grade of \'C\' or better or score of 5 on the Math Placement Test or concurrent enrollment in MATH 151.'),(3,'Discrete Structures','CMSC 203','CMSC',203,'This course introduces the fundamental tools, topics and concepts of discrete mathematics needed to study computer science. This course emphasizes counting methods, proof techniques and problem-solving strategies. Topics include Boolean algebra; set theory; symbolic logic; predicate calculus; number theory; the methods of direct, indirect and inductive proofs; objective functions; equivalence relations; graphs; set partitions; combinatorics; modular arithmetic; summations; and recurrences.',3,'Prerequisite: MATH 140 or MATH 151 with a grade of \'C\' or better.'),(4,'Ethical Issues in Information Technology','CMSC 304','CMSC',304,'A survey course that reviews social issues and the ethical impact of information technology throughout the world. The course examines the policy issues that relate to the use of information technology, such as persona, privacy, rights of access, security, transborder information flow and confidentiality.',3,'Prerequisite: ENGL 100 and (CMSC 202, CMSC 202H, or CMSC 210) with a grade of \'C\' or better.'),(5,'Computer Organization and Assembly Language Programming','CMSC 313','CMSC',313,'This course introduces the student to the low-level abstraction of a computer system from a programmer\'s point of view, with an emphasis on low-level programming. Topics include data representation, assembly language programming, C programming, the process of compiling and linking, low-level memory management, exceptional control flow, and basic processor architecture.',3,'Prerequisite: CMSC 202 and CMSC 203 with a grade of \'C\' or better.'),(6,'Principles of Programming Languages','CMSC 331','CMSC',331,'This course examines the theory, design and implementation of programming languages and provides students with an introduction to programming languages that are likely to be new to them. Topics include specifications of syntax and semantics, declarations, binding, allocation, data structures, data types, control structures, control and data flow, concurrency, and the implementation and execution of programs. The major language paradigms will be described and explored, including imperative, object-oriented, functional, logic programming, concurrent and others. Programming projects will provide experience in several languages.',3,'Prerequisite: CMSC 202 and CMSC 203 with a grade of \'C\' or better.'),(7,'Data Structures','CMSC 341','CMSC',341,'An examination of a range of advanced data structures, with an emphasis on an object-oriented approach. Topics include asymptotic analysis; various binary search trees, including red-black and splay trees; skip lists as alternatives to binary search trees; data structures for multidimensional data such as K-D trees; heaps and priority queues, including binary heaps, binomial heaps, leftist heaps (and/or other mergeable heaps); B-trees for external storage; other commonly used data structures, such as hash tables and disjoint sets. Programming projects in this course will focus on implementation issues for data structures and on empirical analysis of their asymptotic performance.',3,'Prerequisite: CMSC 202 and CMSC 203 with a grade of \'C\' or better.'),(8,'Software Engineering I','CMSC 447','CMSC',447,'This course introduces the basic concepts of software engineering, including software life cycle, requirements analysis and software design methods. Professional ethics in computer science and the social impact of computing are discussed as an integral part of the software development process. Additional topics may include tools for software development, software testing, software metrics and software maintenance. THIS COURSE REQUIRES ANOTHER CMSC 400-LEVEL COURSE AS A PREREQUISITE.',3,'Prerequisite: CMSC 341 and one additional 400-level CMSC course with a grade of \'C\' or better.'),(9,'Computer Architecture','CMSC 411','CMSC',411,'This course covers the design of complex computer systems making heavy use of the components and techniques discussed in CMSC 313, CMPE 212 and CMPE 310. All parts of the computer system - CPU, memory and input/output - are discussed in detail. Topics include information representation, floating-point arithmetic, instructions set design issues (RISC vs. CISC), microprogrammed control, hardwired control, pipelining, memory cashes, bus control and timing, input/output mechanism and issues in the construction of parallel processors.',3,'Prerequisite: CMSC 313 or (CMPE 212 and CMPE 310) with a grade of \'C\' or better.'),(10,'Principles of Operating Systems','CMSC 421','CMSC',421,'An introduction to the fundamentals of operating systems. Topics include interprocess communication, process scheduling, deadlock, memory management, virtual memory, file systems and distributed systems. Formal principles are illustrated with examples and case studies of one or more contemporary operating systems.',3,'Prerequisite: CMSC 341 with a grade of \'C\' or better. CMSC 313 or (CMPE 212 and CMPE 310) with a grade of \'C\' or better.'),(11,'Design and Analysis of Algorithms.','CMSC 441','CMSC',441,'This course studies fundamental algorithms, strategies for designing algorithms, and mathematical tools for analyzing algorithms. Fundamental algorithms studied in this course include algorithms for sorting and searching, hashing, and graph algorithms. Mathematical tools include asymptotic notations and methods for solving recurrences. Algorithm design strategies include the greedy method, divide-and-conquer, dynamic programming, and randomization.',3,'Prerequisite: CMSC 341, (MATH 142 or MATH 152), and (CMPE 320, STAT 355, or STAT 451) with a grade of \'C\' or better.'),(12,'Principles of Computer Security','CMSC 426','CMSC',426,'This course will provide an introduction to computer security, with specific focus on the computing aspects. Topics covered will include basics of computer security including an overview of threat, attack, and adversary models; social engineering; essentials of cryptography; traditional computing security models; malicious software; secure programming; operating system security in practice; trusted operating system design; public policy issues including legal, privacy, and ethical issues; network and database security overview.',3,'Prerequisite: CMSC 341 with a grade of \'C\' or better. CMSC 313 or (CMPE 212 and CMPE 310) with a grade of \'C\' or better.'),(13,'Compiler Design Principles','CMSC 431','CMSC',431,'A detailed study of the design and implementation of a compiler for a high-level programming language. Topics include lexical analysis, parsing techniques (including LL and LR parsers), semantic routines, run-time storage allocation, code generation and optimization.',3,'Prerequisite: CMSC 313, CMSC 331, and CMSC 341 with a grade of \'C\' or better.'),(14,'Computer Graphics','CMSC 435','CMSC',435,'An introduction to the fundamentals of interactive computer graphics. Topics include graphics hardware, line drawing, area filling, clipping, two-dimensional and three-dimensional geometrical transforms, three-dimensional perspective viewing, hidden surface removal, illumination, color and shading models.',3,'Prerequisite: CMSC 313, CMSC 341, and MATH 221 with a grade of \'C\' or better.'),(15,'Software Engineering II','CMSC 448','CMSC',448,'A continuation of the study of software engineering with emphasis on topics not fully covered in CMSC 447. Topics may include software maintenance; metrics; quality assurance; configuration management; deployment; project planning and management; and modern software development processes, techniques and tools. Students will be given multiple individual and cooperative hands-on assignments. Note: Credit will not be given for both CMSC 445 and CMSC 448.',3,'Prerequisite: CMSC 447 with a grade of \'C\' or better.'),(16,'Automata Theory and Formal Languages','CMSC 451','CMSC',451,'This course introduces the basic concepts in the theory of formal languages. Topics include regular grammars and finite automata, context-free grammars and push-down automata, Turing machines and the halting problem, and an introductory treatment of computable and non-computable functions.',3,'Prerequisite: CMSC 202 and CMSC 203 with a grade of \'C\' or better.'),(17,'Numerical Computations','CMSC 455','CMSC',455,'Topics include numerical linear algebra, interpolation, solving non-linear systems and the numerical solution of differential equations. This course also provides some emphasis on numerical algorithms and computation in a parallel environment.',3,'Prerequisite: CMSC 341, MATH 221, and (MATH 142 or MATH 152) with a grade of \'C\' or better.'),(18,'Symbolic Computation','CMSC 456','CMSC',456,'The theme of this course is abstract algebra from an algorithmic perspective. Algorithms for computing in groups, rings, fields, ideals, quotient rings and other algebraic objects are studied. For example, the Coxeter coset enumeration and the Groebner basis algorithms are studied. Algebraic varieties play a key role in this course. The course also covers many applications of symbolic computation, such as applications to algebraic coding theory, robotics and automatic theorem proving. There are various projects using a symbolic computation package such as Maple or Mathematica.',3,'Prerequisite: CMSC 341, MATH 221, and (MATH 142 or MATH 152) with a grade of \'C\' or better.'),(19,'Database Management Systems','CMSC 461','CMSC',461,'This course covers database management and the different data models used to structure the logical view of databases. The course also covers database design and implementation techniques, including file organization, query processing, concurrency control, recovery, integrity and security.',3,'Prerequisite: CMSC 341 or CMSC 341H with a grade of \'C\' or better.'),(20,'Artificial Intelligence','CMSC 471','CMSC',471,'This course provides a broad introduction to artificial intelligence, its sub-fields and their applications. Topics include problem-solving approaches, problem spaces and search, knowledge representation and reasoning, logic and deduction, planning, expert systems, handling uncertainty, learning and natural language understanding.',3,'Prerequisite: CMSC 341 or CMSC 341H with a grade of \'C\' or better.'),(21,'Computer Networks','CMSC 481','CMSC',481,'This course introduces the fundamentals of data communication and computer networking, including circuit and packet switching; network architectures and protocols; local/metropolitan/wide-area networks, OSI and TCP/IP standards; network programming and applications; and network management.',3,'Prerequisite: CMSC 341 or CMSC 341H with a grade of \'C\' or better.'),(22,'Parallel and Distributed Processing','CMSC 483','CMSC',483,'This course provides a project and applications-oriented approach to parallel and distributed programming. Students will learn a specific parallel language and programming environment and will complete a large programming project. Topics include a selected parallel programming language, a survey of parallel and distributed architectures and associated programming styles, an introduction to parallel and distributed algorithms, and a study of trade-offs between computation and communication in parallel processing.',3,'Prerequisite: CMSC 421 with a grade of \'C\' or better.'),(23,'Differential Calculus','MATH 140','MATH',140,'This course covers the fundamentals of the differential calculus with review of notions of analytic geometry and trigonometry as needed. Content includes limits; rate of change and velocity; derivatives and rules of differentiation; differentiation of polynomial, algebraic and trigonometric functions; curve sketching and optimization problems; and differentiation of inverse functions, anti-derivatives and indefinite integrals. Note: Math 140 does not cover all the material of Math 151. It is equivalent to the first quarter of calculus at institutions on the quarter system.',3,'Prerequisite: MATH 150 with a grade of \'C\' or better or score of 5 on the Math Placement Test.'),(24,'Precalculus Mathematics','MATH 150','MATH',150,'This course provides the mathematical preparation necessary for success in calculus. It also provides preparation for basic physics, computer science and engineering science courses. Topics covered include review of functions and graphing techniques; logarithmic and exponential functions; review of basic right-angle trigonometry followed by an extensive treatment of trigonometric functions, identities and applications to the analytic geometry of the conic sections, applications to two-dimensional vectors and to the geometry of complex numbers.',4,'Prerequisite: MATH 106 with a grade of \'C\' or better or score of 4 or 5 on the Math Placement Test.'),(25,'Calculus I','MATH 151','MATH',151,'Topics of this course include limits, continuity, the rate of change, derivatives, differentiations formulas for algebraic, trigonometric, logarithmic, and exponential functions, maxima and minima, integration and computation of areas, the Fundamental Theorem of Calculus, areas and volumes of solids of revolution, and applications. Note: Non-science oriented students should consider MATH 155. Credit will not be given for both MATH 151 and MATH 155.',4,'Prerequisite: MATH 150 with a grade of \'C\' or better or score of 5 on the Math Placement Test.'),(26,'Calculus II','MATH 152','MATH',152,'Topics of this course include inverse functions, methods of integration, improper integrals, hyperbolic functions, sequences and infinite series, power series, Taylor series, conic sections, polar coordinates, and applications.',4,'Prerequisite: MATH 141, MATH 151, MATH 151H, or MATH 155B with a grade of \'C\' or better.'),(27,'Applied Calculus','MATH 155','MATH',155,'Basic ideas of differential and integral calculus, with emphasis on elementary techniques of differentiation and integration with applications, are treated in this course. Technology will be utilized to enhance understanding of the concepts and their applications. Not recommended for students majoring in mathematics, computer science, engineering, or physical sciences. Note: Credit will not be given for both MATH 151 and 155.',4,'Prerequisite: MATH 106 with a grade of \'C\' or better or score of 4 or 5 on the Math Placement Test.'),(28,'Introduction to Linear Algebra','MATH 221','MATH',221,'Topics of this course include: linear equations, Gauss-Jordan reduction, matrices and determinants and their properties, vector spaces and subspaces, basis and dimension, linear transformations, kernel and range, eigenvalues and eigenvectors, and matrix diagonalization.',3,'Prerequisite: MATH 141, MATH 151, or MATH 380 with a grade of \'C\' or better.'),(29,'Applied Statistics I','STAT 355','STAT',355,'This course is an introduction to probability, statistics and statistical computation for students who have knowledge of univariate calculus. Topics include set-theoretic and axiomatic introduction to probability; sample space; events; conditional probability; Bayes theorem; random variables; cumulative distribution functions; probability density functions; probability mass functions; moments and their properties including discussions on mean, variance and the moment generating function; standard univariate distributions such as the Bernoulli, Binomial, Poisson, Exponential; Gamma and Normal and their properties; the Central Limit Theorem (without proof) and its properties and use in statistics; introduction to the concept of randomness in observed data, estimation of unknown parameters, statistical inference and uncertainty quantification; estimation and inference in one and two sample means, proportions; contingency tables and tests for independence of row and column and equality of proportions; introduction to simple linear regression with estimation, inference, analysis of variance, plots and diagnostics. Statistical software like R or Python for estimation, inference and other statistical tasks will be used.',4,'Prerequisite: MATH 152 with a grade of \'C\' or better.'),(30,'Foundations of Biology: Cells, Energy and Organisms','BIOL 141','BIOL',141,'This course for majors provides a broad overview of contemporary biological concepts. Major topics include structure and synthesis of nucleic acids and proteins, molecular genetics, prokaryotic and eukaryotic cell structure and function, biochemistry of energy transformation, and animal and plant development and physiology. This course is designed to prepare students for upper-level biology core and elective courses. It is one of two introductory courses (BIOL 141 and BIOL 142) designed for BIOL, BIOC and BINF majors.',4,'Prerequisite: MATH 150, MATH 151, or MATH 155 with a grade of \'C\' or better or placement into MATH 151.'),(31,'Foundations of Biology: Ecology and Evolution','BIOL 142','BIOL',142,'This course provides a broad overview of contemporary biological concepts. Major topics include fundamental concepts in ecology and evolution and emphasizes the fundamental interrelationship between these two fields of study. Concepts in evolution include a general description of the diversity of life, a review of Mendelian genetics, the causes and consequences of speciation, natural selection and genetic drift. Concepts in ecology will focus on ecological and evolutionary factors that govern population growth and regulation, species distributions, community and ecosystem ecology. This course is designed to prepare students for upper-level biology core and elective courses. It is one of two introductory courses (BIOL 141 & 142) designed for BIOL, BIOC and BINF majors.',4,'Prerequisite: BIOL 141 with a grade of \'C\' or better. MATH 150, MATH 151, or MATH 155 with a grade of \'C\' or better or placement into MATH 151.'),(32,'Principles of Chemistry I','CHEM 101','CHEM',101,'An introduction to chemistry for science majors and other students who require a thorough grounding in the principles of chemistry. Topics treated include the atomic-molecular theory of matter, stoichiometry, states of matter, chemical nomenclature, energetics of chemical and physical processes, solutions, periodic properties, VSEPR, molecular orbital theory and chemistry of familiar elements. Note: Credit may not be obtained for both CHEM 101 and 123.',4,'Prerequisite: MATH 106, MATH 150, MATH 151, or MATH 155 with a grade of \'C\' or better or score of 4 or 5 on the Math Placement Test.'),(33,'Principles of Chemistry II','CHEM 102','CHEM',102,'Principles of chemical and physical equilibrium, liquids and solids, elementary thermodynamics, electron and proton transfer reactions, electrochemistry, chemical kinetics and a further study of the periodic properties of the elements. (Fall/Spring/Summer)',4,'Prerequisite: CHEM 101 or CHEM 101H with a grade of \'C\' or better.'),(34,'Introductory Physics I','PHYS 121','PHYS',121,'This is the first-semester introductory calculus-based physics course. Topics include kinematics, Newton\'s laws, gravitation, conservation laws, rotation, and simple harmonic motion. This course consists of lectures and discussions.',4,'Prerequisite or Corequisite: MATH 151 or MATH 151H.'),(35,'Introductory Physics II','PHYS 122','PHYS',122,'This is the second-semester introductory calculus-based physics course. Topics include thermodynamics, electricity, DC circuits, and magnetism. This course consists of lectures and discussions. (Fall/Spring)',4,'Prerequisite: PHYS 121 or PHYS 121H with a grade of \'C\' or better. Prerequisite or Corequisite: MATH 152 or MATH 152H.'),(36,'Financial Mathematics for Actuaries','STAT 365','STAT',365,'This course is an introduction to the mathematics of interest and the evaluation of interest related products including annuities with non-contingent payments, loans, bonds, general cash flows, portfolios, and immunization. Additional topics discussed include sources of interest rates, stochastic interest rates, and financial instruments such as shorts, swaps, and options. This material includes most of the learning objectives for the Financial Mathematics Exam (called Exam FM by the Society of Actuaries and Exam 2 by the Casualty Actuarial Society.) Also, students not necessarily interested in taking the actuarial exam are encouraged to take this course as an upper-level elective.',3,'Prerequisite: MATH 152 with a grade of \'C\' or better.'),(37,'Atlantic Revolutions','HIST 340','HIST',340,'This course will examine the revolutions that the spread across the Atlantic World from the mid-18th to the mid-19th century, a period some have called the \"Age of Revolutions.\" The primary focus will be exploring the \"successful\" revolutions of the era: the rebellion of the thirteen British American colonies, the internal revolution within France, the independence movement that wound up ending slavery in the French island of Saint-Domingue (Haiti), and the numerous wars of independence in Latin America. Given the breadth of topics, the objective is not to gain an exhaustive understanding of any one revolution, but rather to explore the connections between them all.',3,'Prerequisite: N/A'),(38,'The American Colonies','HIST 341','HIST',341,'A history of the American colonies from their founding to 1774, comparing the social and economic development of the West Indies, New England, mainland South and middle colonies. Topics include patterns of settlement, racial and ethnic interaction, labor, religion, family and gender roles, and cultural achievements.',3,'Prerequisite: N/A'),(39,'First Year Seminar (AH)','FYS 101','FYS',101,'First-Year Seminars are open to all students in their first year at UMBC. Only ONE First-Year Seminar (FYS) can count towards the UMBC General Education Program (GEP) requirements. Any FYS course taken beyond the first FYS will only count for elective credits.',3,'Prerequisite: N/A'),(40,'Elementary French I','FREN 101','FREN',101,'An introduction to French through a communicative approach. Language is learned in a thematic context, based on real-life situations. Listening comprehension and basic speaking skills are emphasized. Aspects of life in French-speaking countries are also presented.',4,'Prerequisite: N/A'),(41,'Elementary French II','FREN 102','FREN',102,'Continuation of FREN 101. Emphasis is on extending skills in spoken French, within the context of real-life situations. A greater amount of reading and writing is included in this course.',4,'Prerequisite: FREN 101 with a grade of \'C\' or better or two years of high school French.'),(42,'Intermediate French I','FREN 201','FREN',201,'Further development of listening comprehension and speaking skills and increased emphasis on reading, writing and cultural knowledge. Focus is on everyday life in France and other French-speaking countries. Can do 3 years of highschool French instead of prerequisite courses.',4,'Prerequisite: FREN 102 or FREN 103 with a grade of \'C\' or better or three years of high school French.'),(43,'Elementary Chinese I','CHIN 101','CHIN',101,'An introduction to Chinese language and culture. Emphasis is on listening comprehension and basic speaking skills. The Pinyin phonetic system of Mandarin Chinese is studied. Chinese characters also are introduced.',4,'Prerequisite: N/A'),(44,'Intermediate Chinese I','CHIN 201','CHIN',201,'Further development of listening comprehension and speaking skills, with an increased emphasis on reading ability and cultural knowledge.',4,'Prerequisite: CHIN 102 with a grade of \'C\' or better or three years of high school Chinese.'),(45,'Intensive Review of Elementary French','FREN 103','FREN',103,'Open to students who have completed level III in high school and who nevertheless are unprepared for FREN 201 either as the result of an interruption of five years in their study of the language or as a result of a weak language background. This course offers an intensive review of Elementary French I and II as an opportunity to improve the student\'s listening, speaking, reading and writing skills. FREN 103 or 102, but not both, may be used toward UMBC\'s GFR language/culture requirement.',4,'Prerequisite: N/A'),(46,'Composition','ENGL 100','ENGL',100,'A course in critical thinking, reading, and composing, with an emphasis on integrating academic research and documentation. Students read and produce work for a variety of purposes and audiences, focusing on strategies for researching, organizing, drafting, sharing, and revising. To satisfy the composition general education requirement, this course must be taken within a student\'s first 30 credit hours of enrollment at UMBC. Recommended Preparation: In consultation with an advisor, a student will self-place into ENGL 100. (Fall/Spring/Summer)',3,'Prerequisite: N/A'),(47,'Advanced Computing','CMSC 210','CMSC',210,'This course strengthens and extends the student\'s programming and problem-solving skills through the use of advanced programming language constructs, pre-defined libraries, and proper software engineering techniques. Topics include program design, debugging, and testing, source code versioning control, use of a software development environment, data formats, web programming, web data extraction, and data visualization. This is the second course for non-computer science, non-computer engineering majors interested in pursuing further study in applied computing.',3,'Prerequisite: CMSC 201 or IS 247 with a grade of \'C\' or better.'),(48,'Principles of Digital Design','CMPE 212','CMPE',212,'This course introduces students to the science of digital design. The topics covered include Boolean algebra; logic theorems; logic circuits and methods for their simplification, including Karnaugh maps and the Quine-McCluskey algorithm; combinational design; electrical characteristics of gates, timing, races and hazards; sequential circuits, their specification via state machines and minimization; principles of register transfer notation; exposure to hardware description language(s); and synthesis tools. This course includes a laboratory. Departmental permission required.',4,'Prerequisite: N/A'),(49,'Systems Design and Programming','CMPE 310','CMPE',310,'This course provides computer engineering students with system design software and hardware experience. This course covers hardware features that support advanced process and memory management in modern architectures such as the Pentium. The details of the entire chipset for 8086 are covered, including topics related to the register architecture, machine language, clock generator, bus controller and memory, I/O and interrupt interface. Other details of a complete computer system are discussed, including I/O bus protocols and support chips, memory chips, interrupt handler hardware and external support chips for disk storage, video and direct memory access. This course includes a laboratory that focuses on assembly language programming and board design software.',4,'Prerequisite: Computer Engineering Gateway. Prerequisite or Corequisite: CMSC 203.'),(50,'Concepts of Biology','BIOL 101','BIOL',101,'A broad overview of contemporary biological science. Major areas include the biochemistry of energy transformation, cell structure and function, Mendelian, molecular and population genetics, development and differentiation, plant and animal physiology, evolution, and ecology. Recommended Preparation: high school biology and chemistry. Note: This introductory biology course is designed for non-majors and may not be used towards the Biochemistry and Molecular Biology, B.S., Bioinformatics and Computational Biology, B.S., Biological Sciences, B.A., or Biological Sciences, B.S.',3,'Prerequisite: N/A'),(51,'Concepts of Biology Lab','BIOL 101L','BIOL',101,'This laboratory course is designed to introduce non-Biology majors to essential laboratory equipment and techniques, as well as basic experimental design.',2,'Prerequisite or Corequisite: BIOL 101 or BIOL 141.'),(52,'Introduction to Public Health','PBHL 100','PBHL',100,'This course provides an overview of public health, giving students foundational knowledge in health policy, traditional public health practice, and health administration. Students will examine different aspects of the public health system and how those parts relate to each other. PBHL 100 also addresses the social, political, and economic factors involved in health and the public health system. Note: A grade of \'C\' or better in the course is required for the major. (Fall/Spring)',3,'Prerequisite: N/A'),(53,'American Government and Politics','POLI 100','POLI',100,'An introduction to American national government and politics. An examination of the ideas, institutions and processes that define the American political system. Intended as a first course in political science for both majors and non-majors.',3,'Prerequisite: N/A'),(54,'Comparative Politics','POLI 260','POLI',260,'This introductory course provides a basic understanding of the fundamental concepts in comparative politics. During the semester, students will learn to think critically and analytically about politics. In addition, students will learn about different political systems across the globe and how they function and provide governance to citizens. Recommended Preparation: Sophomore standing or POLI 100.',3,'Prerequisite: N/A'),(55,'Fundamentals of Music Theory','MUSC 101','MUSC',101,'A study of the fundamentals of music theory, including notation, scale construction, intervals, chords, meter, etc., with emphasis on learning and developing music reading skills. Note: Students planning to continue with more advanced musical studies or students who have some prior studies on music fundamentals should enroll in MUSC 102 Advanced Music Fundamentals instead.',3,'Prerequisite or Corequisite: Not open to students who are enrolled in or have completed MUSC 102.'),(56,'Elementary Chinese II','CHIN 102','CHIN',102,'Continuation of CHIN 101',4,'Prerequisite: CHIN 101 with a grade of \'C\' or better or two years of high school Chinese.'),(57,'Calculus Applications and Infinite Series','MATH 142','MATH',142,'Topics of this course include first introduction to differential equations; further applications of the differential and integral calculus; infinite sequences and series; Taylor and Maclaurin series for functions, including the trigonometric, logarithmic and exponential functions. Note: Completion of this course is equivalent to completion of Math 152. This is equivalent to the third quarter of calculus at institutions on the quarter system.',3,'Prerequisite: MATH 141 with a grade of \'C\' or better.'),(58,'Probability, Statistics, and Random Processes','CMPE 320','CMPE',320,'This course presents the fundamental concepts of probability, statistics and random processes from a computer and electrical engineering perspective, emphasizing applications in communications, signal processing, and machine learning. Students will learn basic methods to analyze and model the probabilistic behavior of engineering systems and to analyze experimental data associated with such systems. A brief use-driven introduction of multivariate calculus concepts will be provided. (Spring)',3,'Prerequisite: MATH 152 or MATH 152H with a grade of \'C\' or better.'),(59,'Probability Theory for Data Science and Statistics','STAT 451','STAT',451,'After a short and rapid refresher on the axioms of probability, univariate random variables and their transformations, CDF, PDF, PMF, MGF and their properties, the course will cover several probability inequalities including Markov, Chebyshev, Jensen; the Weak Law of Large Numbers;  the Central Limit Theorem with a proof based on the MGF; introduction to Borel sigma-algebra and null sets; almost sure convergence; Borel-Cantelli Theorem and the Strong Law of Large Numbers; convergence in distribution in details; Slutsky\'s Theorem; multivariate random variables in depth, including multivariate transformations and the use of the Jacobean; details on the multivariate Normal distribution and its properties including discussions on conditional distributions, transformations and quadratic forms.',3,'Prerequisite: MATH 251 and STAT 355 with a grade of \'C\' or better.'),(60,'Algebra and Elementary Functions','MATH 106','MATH',106,'An introduction to the basic techniques and functions of mathematics. This course is especially recommended for those students who need to brush up due to a shaky high school preparation or for those who haven\'t had a mathematics course in several years. Topics include linear equations and inequalities; quadratic equations; polynomials; and rational functions and their inverses, including the exponential and the logarithm.',3,'Prerequisite: Score of 2 or higher on the Math Placement Test.'),(61,'Integral Calculus','MATH 141','MATH',141,'Topics of this course include computation of areas, definition of the definite integral, integrals of algebraic and trigonometric functions, applications of integrals, the calculus of exponential and logarithmic functions, basic and advanced techniques of integration, numerical integration and improper integrals. Note: The combination of Math 140 and Math 141 includes all of the material of Math 151 and can serve as a prerequisite to Math 152. Math 141 is equivalent to the second quarter of calculus at an institution on the quarter system.',3,'Prerequisite: MATH 140 or MATH155B with a grade of \'C\' or better.'),(62,'Introduction to Optimization for Data Science','MATH 380','MATH',380,'This course provides an introduction to optimization, both in fundamental theory and algorithms, motivated by numerous modern applications from data science, machine learning, and artificial intelligence. It will cover linear programming, first-order algorithms for unconstrained or linear equality constrained optimization, such as gradient descent schemes, stochastic first-order algorithms for large-scale optimization, ADMM methods, as well as certain representative second-order algorithms, e.g., Newton and Quasi-Newton schemes.',3,'Prerequisite: MATH 221, MATH 251, MATH 300, STAT 332, and STAT 355 with a grade of \'C\' or better.'),(63,'Computer Programming II','IS 247','IS',247,'This second course in a sequence continues the development of programming and problem-solving skills, focusing on topics such as: lists, searching and sorting, sets, stacks, queues, trees and an introduction to analyses of algorithm time and space requirements.',3,'Prerequisite: IS 147 and (MATH 151, MATH 151H, or MATH 155) with a grade of \'C\' or better'),(64,'Introduction to Computer Programming','IS 147','IS',147,'This course introduces the basic principles and techniques involved in computer programming and computing. Methods of algorithm development, program development, and program design are taught using an object-oriented programming language. Projects are geared toward those typically encountered in the Information Systems field.',3,'Prerequisite: N/A'),(65,'Multivariable Calculus','MATH 251','MATH',251,'Topics of this course include parametric and polar functions, vectors, lines, planes and surfaces in three dimensions, vector functions and their derivatives, partial derivatives, gradients, directional derivatives, maxima, minima, and Lagrange multipliers, multiple integrals, area, volume, surface area, integration in different coordinate systems, line integral, and the Green\'s, Stokes, and divergence theorems.',4,'Prerequisite: MATH 142 or MATH 152 with a grade of \'C\' or better.'),(66,'Introduction to Mathematical Reasoning','MATH 300','MATH',300,'This course develops fundamentals of mathematical logic and proof writing. Topics will include propositional logic, quantifiers, contradiction and contrapositive, induction, sets, relations, integers, functions, images and pre-images, bijections and inverse functions. LaTeX, a typesetting program for mathematical writing will be introduced. In addition to writing proofs, students will learn to assess the soundness of proofs written by others.',4,'Prerequisite: MATH 221 with a grade of \'C\' or better.');
