CREATE DEFINER=`root`@`localhost` PROCEDURE `get_prereqs`(catalogname varchar(255))
BEGIN
    SELECT c.catalogname,
       agp.and_group_id
	FROM and_group_prereq agp
	JOIN courses c ON agp.prerequisite_id = c.course_id
	JOIN courses course ON agp.course_id = course.course_id
	WHERE course.catalogname = catalogname;
END ;;
