CREATE DEFINER=`root`@`localhost` PROCEDURE `SearchCourses`(
    IN u_category VARCHAR(255),
	IN u_course_num INT,
    IN u_credits INT
    )
BEGIN
	SET @query = 'SELECT * FROM courses WHERE 1=1';
	IF u_category IS NOT NULL THEN
		SET @query = CONCAT(@query, ' AND category = "', u_category, '"');
	END IF;
    IF u_course_num IS NOT NULL THEN
		SET @query = CONCAT(@query, ' AND course_num = ', u_course_num);
	END IF;
    IF u_credits IS NOT NULL THEN
		SET @query = CONCAT(@query, ' AND course_credits = ', u_credits);
	END IF;
    
    PREPARE my_query from @query;
    EXECUTE my_query;
    DEALLOCATE PREPARE my_query;
END ;;
DELIMITER ;
